(() => {
'use strict';
const D=window.IronData, KEY='ironform-premium-v4', LEGACY='ironform-studio-v2';
const $=s=>document.querySelector(s), $$=s=>[...document.querySelectorAll(s)];
const esc=v=>String(v??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const uid=()=>globalThis.crypto?.randomUUID?.()||Date.now().toString(36)+'-'+Math.random().toString(36).slice(2);
const dateKey=(d=new Date())=>`${d.getFullYear()}-${String(d.getMonth()+1).padStart(2,'0')}-${String(d.getDate()).padStart(2,'0')}`;
const plusDate=(key,n)=>{const d=new Date(key+'T12:00:00');d.setDate(d.getDate()+n);return dateKey(d)};
const fmtDate=key=>new Date(key+'T12:00:00').toLocaleDateString('bg-BG',{day:'numeric',month:'short'});
const clock=s=>{const n=Math.ceil(Math.max(0,Number(s)||0));return `${Math.floor(n/60).toString().padStart(2,'0')}:${(n%60).toString().padStart(2,'0')}`};
const focusName=id=>D.focuses.find(x=>x.id===id)?.name||'Мобилност';
const chosenFocuses=p=>Array.isArray(p?.focuses)&&p.focuses.length?p.focuses:[p?.focus||'full'];
const focusList=p=>chosenFocuses(p).map(focusName).join(' · ');
const ex=id=>D.exercises.find(x=>x.id===id)||D.exercises[0];
const paths={play:'m9 5 11 7-11 7V5Z',pause:'M8 5v14M16 5v14',close:'m6 6 12 12M6 18 18 6',arrow:'M5 12h14m-6-6 6 6-6 6',chevron:'m9 5 7 7-7 7',check:'m5 12 4 4L19 6',settings:'M12 8a4 4 0 1 0 0 8 4 4 0 0 0 0-8Zm0-5v2m0 14v2M3 12h2m14 0h2M5.6 5.6 7 7m10 10 1.4 1.4M5.6 18.4 7 17m10-10 1.4-1.4',clock:'M12 8v5l3 2M12 3a9 9 0 1 0 0 18 9 9 0 0 0 0-18',flame:'M13 3c1 5-4 5-2 9 2-1 3-2 3-4 5 4 5 8 2 11-4 4-11 1-10-4 0-4 5-6 7-12Z',sound:'m11 5-6 4H2v6h3l6 4V5Zm4 3c3 2 3 6 0 8m3-11c5 4 5 10 0 14',swap:'M4 7h14l-4-4m4 4-4 4M20 17H6l4 4m-4-4 4-4',skip:'m5 5 10 7L5 19V5Zm14 0v14',expand:'M8 3H3v5m13-5h5v5M3 16v5h5m13-5v5h-5',calendar:'M5 5h14v16H5V5Zm3-3v6m8-6v6M5 11h14',target:'M12 3a9 9 0 1 0 0 18 9 9 0 0 0 0-18Zm0 5a4 4 0 1 0 0 8 4 4 0 0 0 0-8',info:'M12 11v6m0-10v1M12 3a9 9 0 1 0 0 18 9 9 0 0 0 0-18',refresh:'M20 7v5h-5M4 17v-5h5M5 7a8 8 0 0 1 14-1m0 12A8 8 0 0 1 5 19'};
const icon=(name,cls='')=>`<svg class="icon ${cls}" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.7" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true"><path d="${paths[name]||paths.target}"/></svg>`;
const art=(focus,view='front')=>window.IronAnatomy?.render(focus,{view,className:'anatomy-svg'})||'';
const media=id=>window.IronMedia?.[id]||{};
function photo(id){const m=media(id);return m.poster||m.images?.[0]||''}
function thumb(id){const p=photo(id);return p?`<img src="${esc(p)}" alt="${esc(ex(id).name)}" loading="lazy">`:`<div class="thumb-anatomy">${art(ex(id).focus,ex(id).focus==='back'||ex(id).focus==='butt'?'back':'front')}</div>`}
const validProfile=p=>p&&D.goals[p.goal]&&D.levels[p.level]&&D.focuses.some(f=>f.id===p.focus)&&(!p.focuses||(Array.isArray(p.focuses)&&p.focuses.length>0&&p.focuses.length<=D.focuses.length&&new Set(p.focuses).size===p.focuses.length&&p.focuses.every(id=>D.focuses.some(f=>f.id===id))&&p.focuses[0]===p.focus))&&[3,4,5].includes(p.days)&&[5,8,10,12,15,18,20,30,45].includes(p.duration);
const validStep=s=>s&&typeof s.id==='string'&&D.exercises.some(e=>e.id===s.exerciseId)&&['seconds','reps'].includes(s.mode)&&['warmup','main','cooldown'].includes(s.phase)&&Number.isFinite(s.target)&&s.target>0&&s.target<=200&&Number.isFinite(s.rest)&&s.rest>=0&&s.rest<=300;
const validSession=s=>s&&typeof s.id==='string'&&Array.isArray(s.steps)&&s.steps.length>0&&s.steps.length<60&&s.steps.every(validStep);
const validDate=d=>typeof d==='string'&&/^\d{4}-\d{2}-\d{2}$/.test(d)&&Number.isFinite(new Date(d+'T12:00:00').getTime());
const validPlan=p=>p&&typeof p.id==='string'&&validProfile(p.profile)&&validDate(p.created)&&p.days?.length===28&&p.days.every((d,i)=>d&&d.number===i+1&&typeof d.id==='string'&&validDate(d.date)&&(d.rest===true||validSession(d.session)));
const validRun=r=>r&&typeof r.id==='string'&&typeof r.title==='string'&&validDate(r.date)&&Number.isFinite(r.activeMs)&&r.activeMs>=0&&r.activeMs<=86400000&&Number.isInteger(r.completedMain)&&r.completedMain>0&&r.completedMain<60&&['complete','partial'].includes(r.status)&&Array.isArray(r.results);
const validActive=r=>r&&Array.isArray(r.steps)&&r.steps.length>0&&r.steps.every(validStep)&&Number.isInteger(r.stepIndex)&&r.stepIndex>=0&&r.stepIndex<r.steps.length&&Array.isArray(r.results)&&Number.isFinite(r.activeMs)&&r.activeMs>=0&&['work','rest'].includes(r.stage);
const defaults=()=>({version:4,profile:null,plan:null,archives:[],runs:[],active:null,settings:{voice:false,sound:true},legacyHistory:[]});
function load(){try{const raw=JSON.parse(localStorage.getItem(KEY));if(raw?.version===4){const s={...defaults(),...raw};s.runs=Array.isArray(raw.runs)?raw.runs.filter(validRun):[];s.archives=Array.isArray(raw.archives)?raw.archives.filter(validPlan):[];s.legacyHistory=Array.isArray(raw.legacyHistory)?raw.legacyHistory.filter(r=>r&&typeof r.title==='string'&&validDate(r.date)):[];s.settings={voice:false,sound:true,...raw.settings};if(!validPlan(s.plan)){s.plan=null;s.profile=null}else{if((s.plan.version||4)<6){s.plan=upgradePlan(s.plan,s.runs);try{localStorage.setItem(KEY,JSON.stringify(s))}catch{}}s.profile=s.plan.profile;}if(!validActive(s.active))s.active=null;return s}}catch{}const s=defaults();try{const old=JSON.parse(localStorage.getItem(LEGACY));if(Array.isArray(old?.history))s.legacyHistory=old.history;s.legacyBackup=old||null}catch{}return s}
let state=load(), summaryRunId=null, view='home', filter='all', query='', catalogMode='guided', legacyGroup='all', legacyQuery='', legacyLimit=12, selectedDay=1, draft=null, setupStep=0, pendingFocus='full', toastTimer;
function save(){try{localStorage.setItem(KEY,JSON.stringify(state));return true}catch{toast('Няма свободно място за запис. Експортирай данните от настройките.');return false}}
function toast(msg){const el=$('#toast');if(!el)return;el.textContent=msg;el.classList.add('visible');clearTimeout(toastTimer);toastTimer=setTimeout(()=>el.classList.remove('visible'),3500)}
// Four foundational patterns are covered on standard days. An emphasis adds volume without excluding them.
const PATTERNS={squat:'lower','reverse-lunge':'lower','wall-sit':'lower','calf-raise':'lower',pushup:'push','knee-pushup':'push','glute-bridge':'posterior','bird-dog':'posterior',superman:'posterior',plank:'core','dead-bug':'core',crunch:'core','side-plank':'core','mountain-climber':'conditioning'};
const patternOf=id=>PATTERNS[id]||'mobility';
function getPool(focus,level,quiet){const push=level==='beginner'?'knee-pushup':'pushup';const pools={full:['squat',push,'glute-bridge','bird-dog','plank','dead-bug','calf-raise','wall-sit','crunch','reverse-lunge','superman','side-plank'],abs:['dead-bug','plank','crunch','side-plank'],chest:[push],arms:[push],legs:['squat','reverse-lunge','wall-sit','calf-raise'],butt:['glute-bridge','reverse-lunge','squat'],back:['bird-dog','superman','glute-bridge']};let pool=pools[focus]||pools.full;pool=pool.filter(id=>ex(id).level<=(level==='beginner'?1:3));if(!quiet&&level!=='beginner'&&focus==='full')pool=[...pool,'mountain-climber'];return [...new Set(pool)]}
function buildSession(profile,dayNumber=1,focusOverride,options={}){
  const focus=focusOverride||profile.focus||'full',level=profile.level,quiet=profile.quiet,duration=profile.duration||12,light=!!options.light;
  const push=level==='beginner'?'knee-pushup':'pushup';
  const foundation=[dayNumber%2?'squat':'wall-sit',push,dayNumber%2?'glute-bridge':'bird-dog',dayNumber%2?'dead-bug':'plank'];
  const express=duration<=8;
  const desired={5:2,8:3,10:4,12:4,15:5,18:6,20:6,30:8,45:9}[duration]||5;
  const candidates=[...getPool(focus,level,quiet),...getPool('full',level,quiet)];
  const rotated=foundation.slice((dayNumber-1)%4).concat(foundation.slice(0,(dayNumber-1)%4));const accentPool=getPool(focus,level,quiet);const featured=focus==='full'?[]:accentPool.filter(id=>foundation.includes(id)).slice(0,1);const selected=express?[...new Set([...featured,...rotated])].slice(0,desired):foundation.slice();
  for(const id of candidates){if(selected.length>=desired)break;if(!selected.includes(id))selected.push(id)}
  // For focus without a distinct bodyweight movement, give the existing push/posterior movement one extra set.
  const accent=new Set(getPool(focus,level,quiet));
  let sets=duration<=8?2:duration<=20?2:3;
  if(light)sets=Math.min(sets,2);
  const extra=duration===18||duration===20?2:0;
  const steps=[];const add=(id,phase,round,target,rest)=>{const e=ex(id);steps.push({id:uid(),exerciseId:id,phase,round,mode:e.mode,target,rest})};
  const warm=duration>=30?45:25;
  add('march','warmup',1,warm,5);add('arm-circles','warmup',1,warm,5);
  const work=[];
  for(let round=1;round<=sets;round++)for(const id of selected){const e=ex(id);let target=e.target+(level==='advanced'?(e.mode==='seconds'?5:2):0);if(light)target=e.mode==='seconds'?Math.max(15,target-5):Math.max(6,target-2);work.push({id,round,target})}
  if(!light&&extra){for(const id of selected.filter(id=>accent.has(id)).slice(0,extra))work.push({id,round:sets+1,target:ex(id).target})}
  // Emphasis adds at most one additional set to two movements, with a three-set cap per movement.
  if(!light&&!express&&duration>=10){const counts=new Map();for(const w of work)counts.set(w.id,(counts.get(w.id)||0)+1);for(const id of selected.filter(id=>accent.has(id)).slice(0,focus==='full'?2:1)){if((counts.get(id)||0)<3){if(duration<=12){const replace=work.findLastIndex(w=>w.round===2&&w.id!==id);if(replace>=0)work.splice(replace,1)}work.push({id,round:3,target:ex(id).target});counts.set(id,3)}}}
  const base=warm*2+10+60;
  const limits=profile.goal==='strength'?[duration<=8?25:40,90]:profile.goal==='energy'?[15,45]:[20,70];
  const totalWork=()=>work.reduce((n,w)=>n+(ex(w.id).mode==='seconds'?w.target:w.target*(profile.goal==='strength'?4:3)),0);
  const restFor=()=>Math.max(limits[0],Math.min(limits[1],Math.round((duration*60-base-totalWork())/Math.max(1,work.length-1))));
  // Reduce volume before compressing rest if the requested cap is too short for good technique.
  while(work.length>selected.length&&base+totalWork()+restFor()*(work.length-1)>duration*60+60){const remove=work.findLastIndex(w=>w.round>1&&!accent.has(w.id));if(remove>=0)work.splice(remove,1);else work.pop()}
  const rest=restFor();
  for(let i=0;i<work.length;i++){const w=work[i];add(w.id,'main',w.round,w.target,i===work.length-1?0:rest)}
  add('child-pose','cooldown',1,30,0);add('chest-stretch','cooldown',1,30,0);
  const estimatedSeconds=steps.reduce((n,x)=>n+(x.mode==='seconds'?x.target:x.target*(profile.goal==='strength'?4:3))+x.rest,0);
  return {id:uid(),focus,title:focusName(focus),steps,estimatedSeconds,light,express};
}
function upgradePlan(plan,runs=[]){if(plan.version>=6)return plan;const profile={...plan.profile,focuses:chosenFocuses(plan.profile)};let n=0;const schedule=new Set(plan.days.filter(d=>!d.rest).map(d=>d.number));const days=plan.days.map(d=>{if(d.rest)return d;const focus=profile.focuses[n++%profile.focuses.length];if(runs.some(r=>r.planId===plan.id&&r.dayId===d.id&&r.status==='complete'))return d;const light=schedule.has(d.number-1);return {...d,session:buildSession(profile,d.number,focus,{light})}});return {...plan,version:6,profile,days}}
function buildPlan(profile){const id=uid(),created=dateKey(),schedule={3:[0,2,4],4:[0,1,3,5],5:[0,1,2,4,5]}[profile.days]||[0,2,4],focuses=chosenFocuses(profile);let workoutIndex=0;return {id,created,version:6,profile:{...profile,focus:focuses[0],focuses:[...focuses]},days:Array.from({length:28},(_,i)=>{const rest=!schedule.includes(i%7);const focus=rest?null:focuses[workoutIndex++%focuses.length];const light=schedule.includes((i-1)%7);return {id:`${id}:${i+1}`,number:i+1,date:plusDate(created,i),rest,session:rest?null:buildSession(profile,i+1,focus,{light})}})}}
function adaptSession(session,runs=[],planId=null){const copy=structuredClone(session);const relevant=runs.filter(r=>r.planId===planId&&r.focus===session.focus&&r.completedMain>0);const latest=relevant.at(-1);if(!latest||(!latest.effort&&!latest.pain))return copy;const good=relevant.filter(r=>r.status==='complete'&&r.effort==='easy'&&!r.pain).length;let adjustment=0;if(latest.pain||latest.effort==='hard')adjustment=-1;else if(latest.status==='complete'&&latest.effort==='easy')adjustment=Math.min(2,good);for(const s of copy.steps.filter(x=>x.phase==='main')){if(adjustment>0)s.target+=s.mode==='seconds'?3*adjustment:adjustment;else if(adjustment<0){s.target=Math.max(s.mode==='seconds'?10:5,Math.floor(s.target*.9));s.rest=Math.min(120,s.rest+10)}}copy.estimatedSeconds=copy.steps.reduce((n,x)=>n+(x.mode==='seconds'?x.target:x.target*3)+x.rest,0);return copy}
function isDayComplete(day){return state.runs.some(r=>r.planId===state.plan?.id&&r.dayId===day.id&&r.status==='complete')}
function nextDay(){return state.plan?.days.find(d=>!d.rest&&!isDayComplete(d))||null}
function streak(){const dates=new Set(state.runs.filter(r=>r.completedMain>0).map(r=>r.date));let d=dateKey(),n=0;if(!dates.has(d))d=plusDate(d,-1);while(dates.has(d)){n++;d=plusDate(d,-1)}return n}
function completeCount(){return state.plan?.days.filter(d=>!d.rest&&isDayComplete(d)).length||0}
function nav(name){view=name;$$('.view').forEach(x=>x.classList.toggle('active',x.id==='view-'+name));$$('[data-nav]').forEach(x=>{x.classList.toggle('active',x.dataset.nav===name);x.setAttribute('aria-current',x.dataset.nav===name?'page':'false')});render();history.replaceState(null,'','#'+name);window.scrollTo({top:0,behavior:'instant'})}
function header(title,eyebrow,copy=''){return `<div class="page-head"><p class="page-eyebrow">${eyebrow}</p><h1 class="page-title">${title}</h1>${copy?`<p class="muted">${copy}</p>`:''}</div>`}
function focusCard(f){return `<button class="focus-card" data-focus="${f.id}"><div class="focus-art">${art(f.id,f.id==='back'||f.id==='butt'?'back':'front')}</div><span class="focus-title">${f.name}${icon('chevron')}</span><span class="focus-meta">${f.subtitle}</span></button>`}
function renderHome(){const next=nextDay(),session=next?.session,profile=state.profile;const today=new Date().toLocaleDateString('bg-BG',{weekday:'long',day:'numeric',month:'long'});$('#homeContent').innerHTML=`${header('Твоето време.<br><span>Твоята сила.</span>',today)}<article class="hero-card"><div class="hero-copy"><span class="hero-overline">${state.active?'ТРЕНИРОВКАТА ТЕ ЧАКА':profile?'ТВОЯТ ЛИЧЕН ПЛАН':'28 ДНИ. ЕДНО НОВО НАЧАЛО.'}</span><h2>${state.active?'Продължи<br>оттук.':session?focusName(session.focus):profile?'Планът е<br>завършен.':'По-силен.<br>Всеки ден.'}</h2><p>${session?`Ден ${next.number} · ${D.levels[profile.level]}`:'Тренирай у дома. Без уреди.<br>С ясен план и видео насоки.'}</p><div class="hero-badges"><span>${icon('clock')}${session?Math.round(session.estimatedSeconds/60):12} мин</span><span>${icon('target')}Без уреди</span></div></div><button class="btn btn-primary btn-wide" data-action="${state.active?'resume':session?'start-day':profile?'open-progress':'setup'}" ${next?`data-day="${next.number}"`:''}>${icon('play')}${state.active?'Продължи тренировката':session?'Започни тренировката':profile?'Виж постиженията':'Създай моя план'}${icon('arrow')}</button></article><div class="stats-row"><div class="stat">${icon('flame')}<strong>${streak()}</strong><span>дни поред</span></div><div class="stat">${icon('check')}<strong>${state.runs.filter(r=>r.completedMain>0).length}</strong><span>тренировки</span></div><div class="stat">${icon('clock')}<strong>${Math.round(state.runs.reduce((n,r)=>n+r.activeMs,0)/60000)}</strong><span>активни мин</span></div></div>${profile?`<div class="section-head"><h2>Моите 28 дни</h2><button class="text-button" data-go="plan">Виж плана ${icon('arrow')}</button></div><button class="program-card" data-go="plan"><div><span class="page-eyebrow">${D.goals[profile.goal]}</span><h3>${focusList(profile)}</h3><p class="muted">${completeCount()} от ${state.plan.days.filter(d=>!d.rest).length} тренировки</p><div class="progress-line"><i style="width:${completeCount()/state.plan.days.filter(d=>!d.rest).length*100}%"></i></div></div><div class="program-visual">${art(profile.focus,profile.focus==='back'||profile.focus==='butt'?'back':'front')}</div></button>`:''}<div class="section-head"><div><p class="page-eyebrow">ФОКУС ВЪРХУ ТЕБ</p><h2>Избери зона</h2></div><button class="text-button" data-go="discover">Всички ${icon('arrow')}</button></div><div class="focus-grid">${D.focuses.slice(0,6).map(focusCard).join('')}</div><button class="legacy-promo" data-action="open-3d"><span class="legacy-promo-icon">${icon('play')}</span><span><small>ТВОИТЕ КЛИПОВЕ</small><strong>3D демонстрации</strong><em>Бицепс, гърди, гръб, крака и още</em></span>${icon('arrow')}</button><div class="section-head"><h2>Техника преди темпо</h2><button class="text-button" data-go="discover">Библиотека ${icon('arrow')}</button></div>${['pushup','squat','plank'].map(id=>`<button class="workout-row" data-exercise="${id}"><div class="workout-thumb">${thumb(id)}</div><span class="workout-row-copy"><strong>${ex(id).name}</strong><small>${focusName(ex(id).focus)} · Видео и техника</small></span>${icon('play')}</button>`).join('')}<p class="footnote">Избирай вариант, който контролираш. При болка спри движението.</p>`}
function catalogTabs(){return `<div class="catalog-tabs" role="group" aria-label="Вид библиотека"><button class="${catalogMode==='guided'?'selected':''}" data-catalog-mode="guided" aria-pressed="${catalogMode==='guided'}">План у дома</button><button class="${catalogMode==='3d'?'selected':''}" data-catalog-mode="3d" aria-pressed="${catalogMode==='3d'}">3D демонстрации</button></div>`}
let legacyObserver;
function observeLegacyPreviews(){legacyObserver?.disconnect();legacyObserver=new IntersectionObserver(entries=>{for(const entry of entries){const v=entry.target;if(entry.isIntersecting&&document.visibilityState==='visible')v.play().catch(()=>{});else v.pause()}},{threshold:.35});$$('.legacy-tile video').forEach(v=>legacyObserver.observe(v))}
function legacyTile(e,c){return `<button class="exercise-tile legacy-tile" data-legacy-video="${esc(e.id)}"><div class="exercise-tile-media"><video muted loop playsinline preload="none" ${e.poster?`poster="${esc(e.poster)}"`:''} src="${esc(e.video)}" aria-hidden="true" tabindex="-1"></video><span class="play-badge">${icon('expand')}</span></div><strong>${esc(e.name)}</strong><small>${c.groups.find(g=>g.id===e.group)?.name||''} · ${e.local?'Твой клип':'3D видео'}</small></button>`}
function renderLegacy3D(){const c=window.IronLegacy3D;const groups=[{id:'all',name:'Всички'},...c.groups];const results=c.items.filter(e=>(legacyGroup==='all'||e.group===legacyGroup)&&(e.name+' '+(e.originalName||'')+' '+(c.groups.find(g=>g.id===e.group)?.name||'')).toLocaleLowerCase('bg').includes(legacyQuery.toLocaleLowerCase('bg')));const visible=results.slice(0,legacyLimit),local=visible.filter(e=>e.local),remote=visible.filter(e=>!e.local);$('#discoverContent').innerHTML=`${header('Виж движението<br><span>в детайли.</span>','3D ДЕМОНСТРАЦИИ','Клиповете се пускат сами, когато са на екрана.')}${catalogTabs()}<label class="search-field">${icon('target')}<input id="legacySearchInput" type="search" placeholder="Търси упражнение" value="${esc(legacyQuery)}" aria-label="Търси 3D демонстрации"></label><div class="filter-scroll">${groups.map(g=>`<button class="chip ${legacyGroup===g.id?'selected':''}" data-legacy-group="${g.id}" aria-pressed="${legacyGroup===g.id}">${g.name}</button>`).join('')}</div><p class="catalog-count muted">${c.loaded?results.length+' демонстрации':c.loading?'Зареждане на стария каталог…':c.error?'Външният каталог не се зареди · 5 качени клипа':'5 качени клипа'} · автоматично възпроизвеждане без звук</p>${local.length?`<div class="section-head legacy-section"><h2>Твоите качени клипове</h2><span class="muted">${local.length} MP4</span></div><div class="catalog-grid">${local.map(e=>legacyTile(e,c)).join('')}</div>`:''}${remote.length?`<div class="section-head legacy-section"><h2>Още 3D движения</h2><span class="muted">онлайн</span></div><div class="catalog-grid">${remote.map(e=>legacyTile(e,c)).join('')}</div>`:''}${results.length>legacyLimit?`<button class="btn btn-secondary btn-wide legacy-more" data-action="legacy-more">Покажи още ${icon('arrow')}</button>`:''}${!results.length?'<div class="empty-state"><h2>Няма резултати</h2><p>Избери друга мускулна група или търсене.</p></div>':''}<p class="footnote">Твоите пет MP4 са в приложението. Останалите клипове са от запазения външен каталог и изискват интернет.</p>`;observeLegacyPreviews()}
function openLegacy3D(id){const c=window.IronLegacy3D,e=c.items.find(x=>x.id===id);if(!e)return;legacyObserver?.disconnect();$$('.legacy-tile video').forEach(v=>v.pause());if(state.active&&$('#workoutDialog').open)pauseRun();const group=c.groups.find(g=>g.id===e.group);$('#detailContent').innerHTML=`<div class="detail-head"><div><p class="page-eyebrow">${esc(group?.name||'Мускулна група')} · 3D ДЕМОНСТРАЦИЯ</p><h2>${esc(e.name)}</h2></div><button class="icon-button" data-close="detailDialog" aria-label="Затвори">${icon('close')}</button></div><div class="media-stage legacy-stage"><video controls autoplay muted loop playsinline preload="metadata" ${e.local?'':'data-legacy-remote="1"'} ${e.poster?`poster="${esc(e.poster)}"`:''} src="${esc(e.video)}" aria-label="3D демонстрация: ${esc(e.name)}"></video></div><p class="legacy-video-error" hidden>Видеото не се зарежда тук. Използвай връзката към оригиналния клип по-долу.</p><div class="detail-copy"><div class="muscle-summary"><div>${art(e.group==='biceps'||e.group==='triceps'||e.group==='shoulders'?'arms':e.group,e.group==='back'||e.group==='butt'?'back':'front')}</div><span><small class="page-eyebrow">МУСКУЛНА ГРУПА</small><strong>${esc(group?.name||'')}</strong><p>Гледай движението, преди да започнеш упражнението.</p></span></div><p class="muted">${e.local?'Този клип е качен в проекта.':'3D каталог: Lyfta / Gymvisual. Видеото се зарежда през интернет.'}</p>${!e.local?`<a class="text-button source-link" href="${esc(e.video)}" target="_blank" rel="noopener">Отвори оригиналния клип ${icon('arrow')}</a>`:''}</div>`;$('#detailDialog').showModal();$('#detailDialog video').play().catch(()=>{})}
function renderDiscover(){if(catalogMode==='3d'){renderLegacy3D();return}const items=D.exercises.filter(e=>(filter==='all'||e.focus===filter)&&(e.name+' '+focusName(e.focus)).toLocaleLowerCase('bg').includes(query.toLocaleLowerCase('bg')));$('#discoverContent').innerHTML=`${header('Движи се<br><span>с увереност.</span>','БИБЛИОТЕКА С УПРАЖНЕНИЯ','Техника, мускулни зони и демонстрации.')}${catalogTabs()}<label class="search-field">${icon('target')}<input id="searchInput" type="search" placeholder="Намери упражнение" value="${esc(query)}" aria-label="Търси упражнения"></label><div class="filter-scroll">${[{id:'all',name:'Всички'},...D.focuses,{id:'recovery',name:'Мобилност'}].map(f=>`<button class="chip ${filter===f.id?'selected':''}" data-filter="${f.id}" aria-pressed="${filter===f.id}">${f.name}</button>`).join('')}</div><p class="catalog-count muted">${items.length} упражнения · без уреди</p><div class="catalog-grid">${items.map(e=>`<button class="exercise-tile" data-exercise="${e.id}"><div class="exercise-tile-media">${thumb(e.id)}<span class="play-badge">${icon('play')}</span></div><strong>${e.name}</strong><small>${focusName(e.focus)} · ${e.mode==='seconds'?'по време':'повторения'}</small></button>`).join('')}</div>${!items.length?'<div class="empty-state"><h2>Няма такова упражнение</h2><p>Опитай друга дума или зона.</p></div>':''}`}
function renderPlan(){if(!state.plan){$('#planContent').innerHTML=`${header('План, създаден<br><span>за твоя ритъм.</span>','28-ДНЕВНА ПРОГРАМА')}<div class="plan-empty-art">${art('full')}</div><div class="empty-state"><h2>Първата крачка е твоя.</h2><p>Избери цел, зони и ниво. Ще получиш балансирани тренировки с акцент върху избраните зони и дни за възстановяване.</p><button class="btn btn-primary btn-wide" data-action="setup">Създай моя план ${icon('arrow')}</button></div>`;return}const plan=state.plan;const selected=plan.days.find(x=>x.number===selectedDay)||plan.days[0];$('#planContent').innerHTML=`${header('Моят план','ТВОИТЕ СЛЕДВАЩИ 28 ДНИ')}<div class="plan-summary"><div><span class="page-eyebrow">${D.goals[state.profile.goal]}</span><h2>${focusList(state.profile)}</h2><p class="muted">${D.levels[state.profile.level]} · ${state.profile.days} дни / седмица</p><strong>${completeCount()}<small> / ${plan.days.filter(x=>!x.rest).length} сесии</small></strong></div><div class="program-visual">${art(state.profile.focus,state.profile.focus==='back'||state.profile.focus==='butt'?'back':'front')}</div></div><div class="calendar-grid">${plan.days.map(d=>`<button class="calendar-day ${d.rest?'rest':''} ${isDayComplete(d)?'complete':''} ${d.number===selectedDay?'selected':''}" data-select-day="${d.number}" aria-label="Ден ${d.number}, ${d.rest?'възстановяване':focusName(d.session.focus)}${isDayComplete(d)?', завършен':''}" aria-pressed="${d.number===selectedDay}"><small>${d.number}</small>${isDayComplete(d)?icon('check'):d.rest?'<span>—</span>':icon('flame')}</button>`).join('')}</div><div class="calendar-key"><span><i class="key-complete"></i>Завършен</span><span><i></i>Тренировка</span><span>— Почивка</span></div><p class="plan-method">Всеки стандартен ден включва крака, избутване, задна верига и корем. Избраните зони получават допълнителен акцент; поредните дни са по-леки.</p><div class="session-preview"><div class="section-head"><div><p class="page-eyebrow">ДЕН ${selected.number} · ${fmtDate(selected.date)}</p><h2>${selected.rest?'Възстанови силата.':focusName(selected.session.focus)}</h2></div>${isDayComplete(selected)?'<span class="done-label">Завършен ✓</span>':''}</div>${selected.rest?`<p class="muted">Лека разходка, мобилност и спокойствие. Почивката е част от плана.</p>${['child-pose','hamstring-stretch'].map(exerciseRow).join('')}<button class="btn btn-secondary btn-wide" data-action="mobility">Отвори мобилността ${icon('arrow')}</button>`:`<div class="hero-badges"><span>${icon('clock')}~${Math.round(selected.session.estimatedSeconds/60)} мин</span><span>${selected.session.steps.filter(s=>s.phase==='main').length} работни серии</span>${selected.session.light?'<span>Лек ден</span>':''}</div>${sessionSteps(selected.session)}<p class="footnote">Повторенията при стартиране могат да се коригират според последната ти изпълнена сесия и обратната връзка.</p><button class="btn btn-primary btn-wide" data-action="start-day" data-day="${selected.number}">${icon('play')}${isDayComplete(selected)?'Повтори тренировката':'Започни ден '+selected.number}</button>`}</div><button class="text-button plan-edit" data-action="setup">${icon('settings')}Промени настройките на плана</button>`}
function exerciseRow(id){return `<button class="exercise-row" data-exercise="${id}"><div class="workout-thumb">${thumb(id)}</div><span><strong>${ex(id).name}</strong><small>${focusName(ex(id).focus)}</small></span>${icon('play')}</button>`}
function sessionSteps(session){return ['warmup','main','cooldown'].map(phase=>{const steps=session.steps.filter(s=>s.phase===phase);return `<div class="phase-list"><p class="page-eyebrow">${phase==='warmup'?'01 · ЗАГРЯВКА':phase==='main'?'02 · ОСНОВНА ЧАСТ':'03 · ОТПУСКАНЕ'}</p>${steps.map(s=>`<button class="exercise-row" data-exercise="${s.exerciseId}"><div class="workout-thumb">${thumb(s.exerciseId)}</div><span><strong>${ex(s.exerciseId).name}</strong><small>${s.target} ${s.mode==='seconds'?'сек':'повт.'}${s.phase==='main'?' · Кръг '+s.round:''}</small></span>${icon('play')}</button>`).join('')}</div>`}).join('')}
function renderProgress(){const runs=state.runs.filter(r=>r.completedMain>0),today=dateKey();const dates=Array.from({length:7},(_,i)=>plusDate(today,i-6));const mins=dates.map(d=>Math.round(runs.filter(r=>r.date===d).reduce((n,r)=>n+r.activeMs,0)/60000));const max=Math.max(5,...mins);$('#progressContent').innerHTML=`${header('Постоянството<br><span>се вижда.</span>','ТВОЯТ ПРОГРЕС')}<div class="stats-row"><div class="stat"><strong>${runs.length}</strong><span>тренировки</span></div><div class="stat"><strong>${streak()}</strong><span>дни поред</span></div><div class="stat"><strong>${Math.round(runs.reduce((n,r)=>n+r.activeMs,0)/60000)}</strong><span>активни мин</span></div></div><section class="activity-panel"><div class="section-head"><h2>Тази седмица</h2><span class="muted">минути</span></div><div class="activity-chart">${dates.map((d,i)=>`<div><strong>${mins[i]}</strong><i style="height:${Math.max(4,mins[i]/max*100)}px"></i><small>${new Date(d+'T12:00:00').toLocaleDateString('bg-BG',{weekday:'short'})}</small></div>`).join('')}</div></section><div class="section-head"><h2>Моята история</h2><span class="muted">${runs.length} записа</span></div><div class="history-list">${runs.length?runs.slice().reverse().map(r=>`<article class="history-item"><div class="history-muscle">${art(r.focus,r.focus==='back'||r.focus==='butt'?'back':'front')}</div><div><strong>${esc(r.title)}</strong><small>${fmtDate(r.date)} · ${Math.max(1,Math.round(r.activeMs/60000))} мин · ${r.completedMain} серии</small><span class="history-tag">${r.status==='complete'?'Завършена':'Частично изпълнена'}</span></div>${icon('check')}</article>`).join(''):'<div class="empty-state"><h3>Всяка тренировка има значение.</h3><p>След първата сесия тук ще видиш реалното време и изпълнените серии.</p><button class="btn btn-secondary" data-go="home">Към тренировките</button></div>'}</div>${state.legacyHistory.length?`<details class="legacy-history"><summary>${state.legacyHistory.length} записа от предишната версия</summary>${state.legacyHistory.map(r=>`<p>${esc(r.title)} · ${esc(r.date)}</p>`).join('')}</details>`:''}<p class="footnote">Данните се пазят на това устройство. Можеш да изтеглиш резервно копие от настройките.</p>`}
function render(){if(view==='home')renderHome();if(view==='discover')renderDiscover();if(view==='plan')renderPlan();if(view==='progress')renderProgress()}
function openSetup(focus='full'){const previous=state.profile;const focuses=focus==='full'?chosenFocuses(previous):[focus];draft={goal:'fitness',level:'beginner',days:3,duration:12,quiet:true,...previous,focus:focuses[0],focuses:[...focuses]};setupStep=0;renderSetup();$('#setupDialog').showModal()}
function option(key,value,label,copy=''){return `<button class="option-button ${String(draft[key])===String(value)?'selected':''}" data-option="${key}" data-value="${value}" aria-pressed="${String(draft[key])===String(value)}"><strong>${label}</strong>${copy?`<small>${copy}</small>`:''}<span class="option-check">${icon('check')}</span></button>`}
function focusOption(f){const selected=draft.focuses.includes(f.id);return `<button class="option-button ${selected?'selected':''}" data-focus-option="${f.id}" aria-pressed="${selected}"><strong>${f.name}</strong><span class="option-check">${icon('check')}</span></button>`}
function renderSetup(){const content=[`<h3>Какво искаш да постигнеш?</h3><div class="option-grid">${Object.entries(D.goals).map(([k,v])=>option('goal',k,v,{fitness:'Сила, мобилност и навик',strength:'Контролирано темпо и повече почивка',energy:'Повече движение и кратки почивки'}[k])).join('')}</div>`,`<h3>Къде да е фокусът?</h3><p class="setup-note">Избери една или няколко зони. Всяка стандартна сесия включва основни движения; зоните добавят акцент. Без уреди тренировката за гръб и бицепс е ограничена.</p><div class="option-grid option-grid-two">${D.focuses.map(focusOption).join('')}</div><p class="selected-focuses">Избрани: ${focusList(draft)}</p><h3>Какъв е опитът ти?</h3><div class="option-grid">${Object.entries(D.levels).map(([k,v])=>option('level',k,v)).join('')}</div>`,`<h3>Колко дни седмично?</h3><div class="option-grid option-grid-three">${[3,4,5].map(n=>option('days',n,n+' дни')).join('')}</div><h3>Време за сесия</h3><div class="option-grid option-grid-three">${[5,8,10,12,15,18,20,30,45].map(n=>option('duration',n,'~'+n+' мин')).join('')}</div><label class="field toggle-field"><span><strong>Тиха тренировка</strong><small>Без подскоци. Подходящо за дома.</small></span><input id="quietInput" type="checkbox" ${draft.quiet?'checked':''}></label><p class="setup-note">Времето е горна цел. При 5–8 минути сесията е кратка и не покрива всички зони сама по себе си. При 4–5 дни има по-леки дни за възстановяване.</p>`][setupStep];$('#setupContent').innerHTML=`<div class="setup-content"><div class="sheet-head"><div><p class="page-eyebrow">ЛИЧЕН ПЛАН · ${setupStep+1}/3</p><h2>Твоят нов ритъм.</h2></div><button class="icon-button" data-close="setupDialog" aria-label="Затвори">${icon('close')}</button></div><div class="step-indicator">${[0,1,2].map(i=>`<i class="${i<=setupStep?'active':''}"></i>`).join('')}</div>${content}<div class="form-footer">${setupStep?'<button class="btn btn-secondary" data-action="setup-back">Назад</button>':''}<button class="btn btn-primary" data-action="${setupStep===2?'save-plan':'setup-next'}">${setupStep===2?'Създай плана':'Продължи'}${icon('arrow')}</button></div>${state.plan&&setupStep===2?'<p class="footnote">Текущият план ще се архивира. Историята остава запазена.</p>':''}</div>`}
function savePlan(){draft.quiet=$('#quietInput')?.checked??draft.quiet;draft.focus=draft.focuses[0];if(state.plan)state.archives.push(state.plan);state.profile={...draft};state.plan=buildPlan(draft);selectedDay=1;save();$('#setupDialog').close();nav('plan');toast('Планът ти е готов. Започни с Ден 1.')}
function mediaStage(id,context='detail'){const m=media(id);const e=ex(id);const poster=photo(id);if(m.video)return `<video controls autoplay muted loop playsinline preload="metadata" poster="${esc(poster)}" src="${esc(m.video)}" aria-label="Демонстрация: ${esc(e.name)}"></video>`;if(m.youtube)return `<div class="auto-video"><iframe src="https://www.youtube-nocookie.com/embed/${encodeURIComponent(m.youtube)}?autoplay=1&mute=1&playsinline=1&enablejsapi=1&rel=0&cc_load_policy=1&loop=1&playlist=${encodeURIComponent(m.youtube)}" title="${esc(e.name)} — видео демонстрация" allow="autoplay; encrypted-media; picture-in-picture" allowfullscreen referrerpolicy="strict-origin-when-cross-origin"></iframe><a class="video-fallback-link" target="_blank" rel="noopener" href="https://www.youtube.com/watch?v=${encodeURIComponent(m.youtube)}">Отвори видеото ${icon('arrow')}</a></div>`;return `<div class="media-fallback">${poster?`<img src="${esc(poster)}" alt="Начална позиция: ${esc(e.name)}">`:art(e.focus,e.focus==='back'||e.focus==='butt'?'back':'front')}${m.images?.length>1?`<button class="media-play" data-show-position="${id}" aria-label="Виж следващата позиция">${icon('swap')}<span>Виж двете позиции</span></button>`:''}</div>`}
function openDetail(id){if(state.active&&$('#workoutDialog').open)pauseRun();const e=ex(id),m=media(id);$('#detailContent').innerHTML=`<div class="detail-head"><div><p class="page-eyebrow">${focusName(e.focus)} · ТЕХНИКА</p><h2>${e.name}</h2></div><button class="icon-button" data-close="detailDialog" aria-label="Затвори">${icon('close')}</button></div><div class="media-stage" id="detailMedia">${mediaStage(id)}</div><div class="detail-copy"><div class="hero-badges"><span>${e.mode==='seconds'?'По време':'Повторения'}</span><span>Без уреди</span><span>${e.level===1?'Основно':'Предизвикателно'}</span></div><p>${e.description}</p><ol class="technique-list">${e.cues.map(c=>`<li>${c}</li>`).join('')}</ol><div class="muscle-summary"><div>${art(e.focus,e.focus==='back'||e.focus==='butt'?'back':'front')}</div><span><small class="page-eyebrow">ОСНОВЕН ФОКУС</small><strong>${focusName(e.focus)}</strong><p>Оцветените зони показват основните мускулни групи.</p></span></div><div class="easier-note"><strong>По-лесен вариант</strong><p>${e.easier}</p></div>${m.sourceUrl?`<a class="text-button source-link" href="${esc(m.sourceUrl)}" target="_blank" rel="noopener">${m.youtube?'Видео: '+esc(m.author||'източник'):'Източник на демонстрацията'} ${icon('arrow')}</a>`:''}</div>`;$('#detailDialog').showModal()}
function playVideo(id,button){const m=media(id);if(!m.youtube)return;const inDetail=$('#detailDialog').open;if(state.active&&state.active.running)pauseRun();const stage=inDetail?$('#detailMedia'):$('#workoutDialog .media-stage');stage.innerHTML=`<iframe src="https://www.youtube-nocookie.com/embed/${encodeURIComponent(m.youtube)}?autoplay=1&playsinline=1&enablejsapi=1&rel=0&cc_load_policy=1" title="${esc(ex(id).name)} — видео демонстрация" allow="autoplay; encrypted-media; picture-in-picture" allowfullscreen referrerpolicy="strict-origin-when-cross-origin"></iframe><a class="video-fallback-link" target="_blank" rel="noopener" href="https://www.youtube.com/watch?v=${encodeURIComponent(m.youtube)}">Не се зарежда? Отвори клипа ${icon('arrow')}</a>`}
function elapsed(run=state.active){return run?(run.activeMs||0)+(run.activeSince?Date.now()-run.activeSince:0):0}
function pauseMedia(){$$('video').forEach(v=>v.pause());$$('iframe').forEach(f=>{try{f.contentWindow.postMessage(JSON.stringify({event:'command',func:'pauseVideo',args:[]}), 'https://www.youtube-nocookie.com')}catch{}});window.speechSynthesis?.cancel()}
function pauseRun(){const r=state.active;if(!r)return;if(r.running){r.remaining=r.deadline?Math.max(0,(r.deadline-Date.now())/1000):r.remaining;r.activeMs=elapsed(r);r.activeSince=null;r.running=false;r.deadline=null;save()}pauseMedia();if($('#workoutDialog').open)renderPlayer()}
function launchRun(session,day=null){if(state.active){$('#detailDialog').open&&$('#detailDialog').close();$('#workoutDialog').showModal();renderPlayer();toast('Продължи текущата сесия или я приключи.');return}state.active={id:uid(),planId:day?state.plan.id:null,dayId:day?.id||null,title:session.title,focus:session.focus,steps:adaptSession(session,state.runs,day?state.plan.id:null).steps,stepIndex:0,stage:'work',remaining:session.steps[0].target,running:false,deadline:null,activeMs:0,activeSince:null,startedAt:new Date().toISOString(),results:[]};save();$('#workoutDialog').showModal();renderPlayer()}
function currentStep(){return state.active?.steps[state.active.stepIndex]}
function renderPlayer(){const r=state.active;if(!r)return;const s=currentStep(),e=ex(s.exerciseId),rest=r.stage==='rest';$('#workoutContent').innerHTML=`<div class="session-player"><div class="player-head"><button class="icon-button" data-action="leave-run" aria-label="Затвори и запази">${icon('close')}</button><span>${rest?'ПОЧИВКА':s.phase==='warmup'?'ЗАГРЯВКА':s.phase==='cooldown'?'ОТПУСКАНЕ':'ОСНОВНА ЧАСТ'}</span><button class="icon-button ${state.settings.voice?'selected':''}" data-action="voice" aria-label="${state.settings.voice?'Изключи':'Включи'} гласови инструкции" aria-pressed="${state.settings.voice}">${icon('sound')}</button></div><div class="player-progress"><i style="width:${r.stepIndex/r.steps.length*100}%"></i></div><div class="player-step-count"><span>${r.stepIndex+1} / ${r.steps.length}</span><span id="elapsedTime">${clock(elapsed()/1000)}</span></div><div class="media-stage player-media">${mediaStage(rest?(r.steps[r.stepIndex+1]?.exerciseId||e.id):e.id,'player')}</div><div class="player-body"><span class="phase-pill">${rest?'ВЪЗСТАНОВЯВАНЕ':s.phase==='main'?'КРЪГ '+s.round:'ПОДГОТОВКА'}</span><h2 class="player-title">${rest?'Поеми си дъх.':e.name}</h2>${rest?`<p class="muted">Следва: ${esc(ex(r.steps[r.stepIndex+1]?.exerciseId||s.exerciseId).name)}</p>`:`<p class="player-cue">${e.cues[0]}</p>`}<div class="player-prescription ${rest||s.mode==='seconds'?'timed':''}">${rest||s.mode==='seconds'?`<div class="timer-ring"><strong id="runTimer">${clock(r.remaining)}</strong><span>${rest?'почивка':'секунди'}</span></div>`:`<strong>${s.target}<small>повторения</small></strong><label class="reps-adjust">Изпълнени<input id="repInput" type="number" inputmode="numeric" min="1" max="200" value="${s.target}" aria-label="Изпълнени повторения"></label>`}</div><div class="player-controls"><button class="btn ${r.running?'btn-secondary':'btn-primary'} btn-wide" data-action="toggle-run">${icon(r.running?'pause':'play')}${r.running?'Пауза':rest?'Продължи почивката':'Старт'}</button>${!rest&&s.mode==='reps'?`<button class="btn btn-primary btn-wide" data-action="done-step" ${!r.running?'disabled':''}>Готово ${icon('check')}</button>`:''}${rest?'<button class="btn btn-ghost btn-wide" data-action="skip-rest">Пропусни почивката</button>':''}</div><div class="player-footer">${!rest?`<button data-action="swap-step">${icon('swap')}Смени</button><button data-exercise="${e.id}">${icon('info')}Техника</button><button data-action="skip-step">${icon('skip')}Пропусни</button>`:`<button data-action="add-rest">+15 сек почивка</button>`}</div><button class="text-button end-session" data-action="finish-now">Приключи сесията сега</button><p class="footnote">${r.running?'Дишай спокойно и пази техниката.':'Натисни Старт, когато си готов.'}</p></div></div>`}
function speak(text){if(!state.settings.voice||!window.speechSynthesis)return;window.speechSynthesis.cancel();const u=new SpeechSynthesisUtterance(text);u.lang='bg-BG';u.rate=.95;window.speechSynthesis.speak(u)}
function toggleRun(){const r=state.active;if(!r)return;if(r.running){pauseRun();return}const s=currentStep();r.running=true;r.activeSince=Date.now();r.lastHeartbeat=Date.now();if(r.stage==='rest'||s.mode==='seconds')r.deadline=Date.now()+Math.max(.5,r.remaining)*1000;save();renderPlayer();speak(r.stage==='rest'?'Почивка':`${ex(s.exerciseId).name}. ${s.target} ${s.mode==='seconds'?'секунди':'повторения'}. ${ex(s.exerciseId).cues[0]}`)}
function advanceStep(){const r=state.active;r.stepIndex++;if(r.stepIndex>=r.steps.length){finishRun();return}const s=currentStep();r.stage='work';r.running=false;r.deadline=null;r.remaining=s.mode==='seconds'?s.target:0;r.activeSince=null;save();renderPlayer()}
function completeStep(skipped=false){const r=state.active;if(!r||r.stage!=='work')return;const s=currentStep();let value=s.target;if(s.mode==='reps'&&!skipped){value=Number($('#repInput')?.value);if(!Number.isFinite(value)||value<1||value>200||!Number.isInteger(value)){toast('Въведи цяло число от 1 до 200.');return}}r.activeMs=elapsed(r);r.activeSince=null;r.running=false;r.deadline=null;r.results.push({stepId:s.id,exerciseId:s.exerciseId,phase:s.phase,skipped,value:skipped?0:value,mode:s.mode});pauseMedia();if(!skipped&&s.rest>0&&r.stepIndex<r.steps.length-1){r.stage='rest';r.remaining=s.rest;save();renderPlayer();toggleRun()}else advanceStep()}
function skipRest(){const r=state.active;if(!r||r.stage!=='rest')return;r.activeMs=elapsed(r);r.activeSince=null;r.running=false;r.deadline=null;pauseMedia();advanceStep()}
function swapStep(){pauseRun();const r=state.active,s=currentStep(),e=ex(s.exerciseId);const list=D.exercises.filter(x=>x.focus===e.focus&&x.id!==e.id&&x.level<=(state.profile?.level==='beginner'?1:3));if(!list.length){toast('За това движение използвай по-лесния вариант в Техника.');return}const replacement=list[Math.floor(Math.random()*list.length)];s.exerciseId=replacement.id;s.mode=replacement.mode;s.target=replacement.target;r.remaining=s.mode==='seconds'?s.target:0;save();renderPlayer();toast('Движението е сменено само за тази сесия.')}
function finishRun(){const r=state.active;if(!r)return;r.activeMs=elapsed(r);pauseMedia();const main=r.results.filter(x=>x.phase==='main'&&!x.skipped),allMain=r.steps.filter(x=>x.phase==='main');const record={id:r.id,planId:r.planId,dayId:r.dayId,title:r.title,focus:r.focus,date:dateKey(),activeMs:r.activeMs,completedMain:main.length,skipped:r.results.filter(x=>x.skipped).length,status:main.length===allMain.length?'complete':'partial',results:r.results};if(main.length>0)state.runs.push(record);summaryRunId=main.length?record.id:null;state.active=null;save();$('#workoutContent').innerHTML=`<div class="completion"><div class="completion-emblem">${icon(main.length?'check':'info')}</div><p class="page-eyebrow">${main.length?'СЕСИЯТА Е ЗАПАЗЕНА':'СЕСИЯТА Е ПРИКЛЮЧЕНА'}</p><h2>${main.length?'Силата е в<br>постоянството.':'Върни се,<br>когато си готов.'}</h2><p class="muted">${main.length?record.status==='complete'?'Изпълни всички работни серии. Добра работа.':'Записахме изпълнените серии. Пропуснатите не се броят.':'Няма изпълнени работни серии. Тази сесия не се брои за завършена тренировка.'}</p><div class="completion-stats"><div><strong>${clock(record.activeMs/1000)}</strong><span>активно време</span></div><div><strong>${main.length}</strong><span>работни серии</span></div><div><strong>${new Set(main.map(x=>x.exerciseId)).size}</strong><span>упражнения</span></div></div>${main.length?`<div class="effort-feedback"><strong>Как беше натоварването?</strong><p>Отговорът помага да настроим следващата тренировка.</p><div class="effort-options"><button data-effort="easy" aria-pressed="false">Леко</button><button data-effort="okay" aria-pressed="false">Точно</button><button data-effort="hard" aria-pressed="false">Трудно</button></div><button class="pain-option" data-action="pain-feedback" aria-pressed="false">Имах болка или дискомфорт</button></div>`:''}<div class="completion-art">${art(r.focus,r.focus==='back'||r.focus==='butt'?'back':'front')}</div><button class="btn btn-primary btn-wide" data-action="close-summary">${main.length?'Виж прогреса':'Към началото'}${icon('arrow')}</button></div>`;render()}
function tick(){const r=state.active;if(!r?.running)return;if(Date.now()-(r.lastHeartbeat||0)>3000){r.lastHeartbeat=Date.now();if(r.deadline)r.remaining=Math.max(0,(r.deadline-Date.now())/1000);save()}const elapsedEl=$('#elapsedTime');if(elapsedEl)elapsedEl.textContent=clock(elapsed()/1000);if(!r.deadline)return;const left=Math.max(0,(r.deadline-Date.now())/1000);const timer=$('#runTimer');if(timer)timer.textContent=clock(left);if(left<=0){if(r.stage==='rest')skipRest();else completeStep(false)}}
function openSettings(){$('#settingsContent').innerHTML=`<div class="setup-content"><div class="sheet-head"><div><p class="page-eyebrow">IRONFORM</p><h2>Твоите настройки</h2></div><button class="icon-button" data-close="settingsDialog" aria-label="Затвори">${icon('close')}</button></div><div class="settings-list"><label class="field toggle-field"><span><strong>Гласови инструкции</strong><small>Според гласовете на устройството.</small></span><input id="voiceSetting" type="checkbox" ${state.settings.voice?'checked':''}></label><button class="btn btn-secondary btn-wide" data-action="export">Изтегли резервно копие ${icon('arrow')}</button><label class="btn btn-ghost btn-wide import-label">Възстанови данни<input id="importFile" type="file" accept="application/json,.json" hidden></label><p class="footnote">Плановете се пазят в този браузър. Нов план не изтрива историята. За друго устройство използвай резервно копие.</p><details class="media-credits"><summary>Медии и източници</summary><p>Анатомия: react-native-body-highlighter, MIT. Кадри и видеа: източникът е посочен към всяко упражнение.</p><a href="assets/LICENSE-media.md" target="_blank">Пълни лицензи и автори</a></details></div></div>`;$('#settingsDialog').showModal()}
function exportState(){pauseRun();const blob=new Blob([JSON.stringify(state,null,2)],{type:'application/json'});const a=document.createElement('a');a.href=URL.createObjectURL(blob);a.download='ironform-backup-'+dateKey()+'.json';a.click();setTimeout(()=>URL.revokeObjectURL(a.href),1000)}
function init(){if(state.active){const r=state.active;if(r.running&&r.activeSince){const checkpoint=Math.min(Date.now(),r.lastHeartbeat||r.activeSince);r.activeMs+=Math.max(0,checkpoint-r.activeSince);r.remaining=r.deadline?Math.max(0,(r.deadline-checkpoint)/1000):r.remaining}r.activeSince=null;r.running=false;r.deadline=null;save()}const hash=location.hash.slice(1);if(['home','discover','plan','progress'].includes(hash))view=hash;nav(view);document.addEventListener('click',event=>{const b=event.target.closest('button,a');if(!b)return;const go=b.dataset.nav||b.dataset.go;if(go){nav(go);return}if(b.dataset.close){$('#'+b.dataset.close).close();return}if(b.dataset.focus){openSetup(b.dataset.focus);return}if(b.dataset.catalogMode){catalogMode=b.dataset.catalogMode;renderDiscover();if(catalogMode==='3d'&&!window.IronLegacy3D.loaded){window.IronLegacy3D.load().then(()=>{if(catalogMode==='3d'&&view==='discover')renderDiscover()})}return}if(b.dataset.legacyGroup){legacyGroup=b.dataset.legacyGroup;legacyLimit=12;renderDiscover();return}if(b.dataset.legacyVideo){openLegacy3D(b.dataset.legacyVideo);return}if(b.dataset.effort){const run=state.runs.find(x=>x.id===summaryRunId);if(run){run.effort=b.dataset.effort;save();$$('[data-effort]').forEach(x=>x.setAttribute('aria-pressed',String(x.dataset.effort===run.effort)));toast('Следващата сесия ще отчете обратната връзка.')}return}if(b.dataset.filter){filter=b.dataset.filter;renderDiscover();return}if(b.dataset.exercise){openDetail(b.dataset.exercise);return}if(b.dataset.playVideo){playVideo(b.dataset.playVideo,b);return}if(b.dataset.showPosition){const id=b.dataset.showPosition,m=media(id),img=b.closest('.media-stage').querySelector('img');if(img&&m.images?.length){const next=(Number(img.dataset.position||0)+1)%m.images.length;img.src=m.images[next];img.dataset.position=next;b.querySelector('span').textContent=`Позиция ${next+1} / ${m.images.length}`}return}if(b.dataset.selectDay){selectedDay=Number(b.dataset.selectDay);renderPlan();return}if(b.dataset.focusOption){const id=b.dataset.focusOption;draft.focuses=draft.focuses.includes(id)?(draft.focuses.length===1?draft.focuses:draft.focuses.filter(x=>x!==id)):[...draft.focuses,id];draft.focus=draft.focuses[0];renderSetup();return}if(b.dataset.option){let value=b.dataset.value;if(['days','duration'].includes(b.dataset.option))value=Number(value);draft[b.dataset.option]=value;renderSetup();return}const a=b.dataset.action;if(a==='setup')openSetup();else if(a==='settings')openSettings();else if(a==='pain-feedback'){const run=state.runs.find(x=>x.id===summaryRunId);if(run){run.pain=!run.pain;save();b.setAttribute('aria-pressed',String(run.pain));toast(run.pain?'Следващата сесия ще е по-лека. При продължаваща болка потърси специалист.':'Отбелязването е премахнато.')}}else if(a==='open-3d'){catalogMode='3d';nav('discover');window.IronLegacy3D.load().then(()=>{if(catalogMode==='3d'&&view==='discover')renderDiscover()})}else if(a==='legacy-more'){legacyLimit+=12;renderDiscover()}else if(a==='setup-next'){setupStep=Math.min(2,setupStep+1);renderSetup()}else if(a==='setup-back'){setupStep=Math.max(0,setupStep-1);renderSetup()}else if(a==='save-plan')savePlan();else if(a==='open-progress')nav('progress');else if(a==='start-day'){const day=state.plan?.days.find(d=>d.number===Number(b.dataset.day));if(day?.session)launchRun(day.session,day)}else if(a==='resume'){if(state.active){$('#workoutDialog').showModal();renderPlayer()}}else if(a==='mobility'){filter='recovery';nav('discover')}else if(a==='toggle-run')toggleRun();else if(a==='done-step')completeStep();else if(a==='finish-now')finishRun();else if(a==='skip-step')completeStep(true);else if(a==='skip-rest')skipRest();else if(a==='add-rest'){const r=state.active;if(r.stage==='rest'){if(r.running)r.deadline+=15000;else r.remaining+=15;save();renderPlayer()}}else if(a==='swap-step')swapStep();else if(a==='leave-run'){pauseRun();$('#workoutDialog').close();render()}else if(a==='voice'){state.settings.voice=!state.settings.voice;save();if(!state.settings.voice)window.speechSynthesis?.cancel();renderPlayer()}else if(a==='close-summary'){$('#workoutDialog').close();nav(state.runs.length?'progress':'home')}else if(a==='export')exportState()});document.addEventListener('input',event=>{if(event.target.id==='legacySearchInput'){const start=event.target.selectionStart;legacyQuery=event.target.value;legacyLimit=12;renderDiscover();const input=$('#legacySearchInput');input.focus();try{input.setSelectionRange(start,start)}catch{}}if(event.target.id==='searchInput'){const start=event.target.selectionStart;query=event.target.value;renderDiscover();const input=$('#searchInput');input.focus();try{input.setSelectionRange(start,start)}catch{}}if(event.target.id==='voiceSetting'){state.settings.voice=event.target.checked;save()}});document.addEventListener('change',async event=>{if(event.target.id==='quietInput'){draft.quiet=event.target.checked;return}if(event.target.id!=='importFile')return;const file=event.target.files?.[0];if(!file)return;if(file.size>5*1024*1024){toast('Файлът е прекалено голям.');return}try{const incoming=JSON.parse(await file.text());if(incoming.version!==4||!Array.isArray(incoming.runs)||!Array.isArray(incoming.archives))throw Error();if(incoming.plan&&!validPlan(incoming.plan))throw Error();if(!incoming.runs.every(validRun)||!incoming.archives.every(validPlan))throw Error();const ids=new Set(state.runs.map(r=>r.id));for(const r of incoming.runs){if(r.id&&!ids.has(r.id)&&Number.isFinite(r.activeMs)){state.runs.push(r);ids.add(r.id)}}const archivedIds=new Set(state.archives.map(p=>p.id));for(const plan of incoming.archives){if(!archivedIds.has(plan.id)){state.archives.push(plan);archivedIds.add(plan.id)}}if(!state.plan&&incoming.plan){state.plan=incoming.plan;state.profile=incoming.plan.profile}save();$('#settingsDialog').close();render();toast('Резервното копие е възстановено.')}catch{toast('Това не е валидно резервно копие на IronForm.')}});['detailDialog','workoutDialog'].forEach(id=>{$('#'+id).addEventListener('close',()=>{pauseMedia();if(id==='workoutDialog'&&state.active)pauseRun();if(id==='detailDialog'&&catalogMode==='3d'&&view==='discover')observeLegacyPreviews()})});$('#workoutDialog').addEventListener('cancel',()=>pauseRun());document.addEventListener('error',event=>{const img=event.target;if(img.tagName==='VIDEO'&&img.dataset.legacyRemote){const note=$('#detailDialog .legacy-video-error');if(note)note.hidden=false;return}if(img.tagName==='IMG'&&!img.dataset.failed){img.dataset.failed='1';img.style.display='none';const parent=img.parentElement;parent.classList.add('image-fallback');if(!parent.querySelector('svg'))parent.insertAdjacentHTML('afterbegin',art(D.exercises.find(e=>img.alt.includes(e.name))?.focus||'full'))}},true);document.addEventListener('visibilitychange',()=>{if(document.hidden)pauseRun()});window.addEventListener('pagehide',pauseRun);setInterval(tick,250)}
window.IronEngine={buildPlan,buildSession,getPool,upgradePlan,adaptSession,patternOf,dateKey,plusDate,clock};
document.addEventListener('DOMContentLoaded',init);
})();
